-- PostgreSQL 18's virtual generated columns: the default kind when STORED is
-- not written, computed values in queries, NULL in trigger rows, `virtual` in
-- failing-row details, and the definitions PostgreSQL refuses for them.
CREATE TABLE t365 (a int, b int GENERATED ALWAYS AS (a * 2),
  c int GENERATED ALWAYS AS (a + 1) VIRTUAL, d int GENERATED ALWAYS AS (a * 3) STORED);
SELECT attname, attgenerated FROM pg_attribute
  WHERE attrelid = 't365'::regclass AND attnum > 0 ORDER BY attnum;
SELECT column_name, is_generated, generation_expression FROM information_schema.columns
  WHERE table_name = 't365' ORDER BY ordinal_position;
INSERT INTO t365 (a) VALUES (1), (2);
SELECT * FROM t365 ORDER BY a;
UPDATE t365 SET a = 10 WHERE a = 1;
SELECT * FROM t365 ORDER BY a;
INSERT INTO t365 VALUES (3, 6);
INSERT INTO t365 (a, b) VALUES (3, DEFAULT);
UPDATE t365 SET b = 1;
SELECT b FROM t365 WHERE b > 5 ORDER BY b;
CREATE INDEX ON t365 (b);
CREATE INDEX ON t365 ((b + 1));
CREATE INDEX ON t365 (a) WHERE b > 1;
ALTER TABLE t365 ADD PRIMARY KEY (b);
ALTER TABLE t365 ADD UNIQUE (b);
ALTER TABLE t365 ADD CONSTRAINT ck365 CHECK (b > 0);
INSERT INTO t365 (a) VALUES (-5);
CREATE STATISTICS st365 ON a, b FROM t365;
CREATE FUNCTION f365(int) RETURNS int IMMUTABLE LANGUAGE sql AS 'SELECT $1';
CREATE TABLE f365t (a int, b int GENERATED ALWAYS AS (f365(a)));
CREATE DOMAIN d365 AS int;
CREATE TABLE d365t (a int, b d365 GENERATED ALWAYS AS (a));
CREATE TYPE mood365 AS ENUM ('a', 'b');
CREATE TABLE e365t (a mood365, b mood365 GENERATED ALWAYS AS (a));
CREATE TABLE r365t (a int, b text GENERATED ALWAYS AS (a::text::regclass::text));
CREATE TABLE n365 (a int, b int GENERATED ALWAYS AS (a) VIRTUAL NOT NULL);
INSERT INTO n365 VALUES (NULL);
ALTER TABLE t365 ALTER COLUMN b DROP EXPRESSION;
ALTER TABLE t365 ALTER COLUMN b SET EXPRESSION AS (a * 5);
ALTER TABLE t365 DROP CONSTRAINT ck365;
ALTER TABLE t365 ALTER COLUMN b SET EXPRESSION AS (a * 5);
ALTER TABLE t365 ADD COLUMN e int GENERATED ALWAYS AS (a - 1);
SELECT * FROM t365 ORDER BY a;
CREATE TABLE ref365 (x int PRIMARY KEY);
CREATE TABLE fk365 (a int, b int GENERATED ALWAYS AS (a) REFERENCES ref365);
COPY t365 (a, b) TO stdout;
CREATE FUNCTION trg365() RETURNS trigger LANGUAGE plpgsql AS
  $$ BEGIN RAISE NOTICE 'row: % old: %', new, old; RETURN new; END $$;
CREATE TRIGGER t365b BEFORE INSERT OR UPDATE ON t365 FOR EACH ROW EXECUTE FUNCTION trg365();
CREATE TRIGGER t365a AFTER INSERT OR UPDATE ON t365 FOR EACH ROW EXECUTE FUNCTION trg365();
INSERT INTO t365 (a) VALUES (7);
UPDATE t365 SET a = 8 WHERE a = 7 RETURNING *;
CREATE TRIGGER t365w BEFORE UPDATE ON t365 FOR EACH ROW WHEN (new.b > 0)
  EXECUTE FUNCTION trg365();
CREATE TABLE l365 (LIKE t365 INCLUDING GENERATED);
SELECT attname, attgenerated FROM pg_attribute
  WHERE attrelid = 'l365'::regclass AND attnum > 0 ORDER BY attnum;
CREATE TABLE p365 (a int, b int GENERATED ALWAYS AS (a + 1) VIRTUAL) PARTITION BY RANGE (a);
CREATE TABLE p365a PARTITION OF p365 FOR VALUES FROM (0) TO (10);
CREATE TABLE p365b (a int, b int GENERATED ALWAYS AS (a + 1) STORED);
ALTER TABLE p365 ATTACH PARTITION p365b FOR VALUES FROM (10) TO (20);
CREATE TABLE k365 (a int, b int GENERATED ALWAYS AS (a + 1) VIRTUAL) PARTITION BY RANGE (b);
INSERT INTO p365 VALUES (1);
SELECT * FROM p365;
CREATE TABLE ty365 (a int, b int GENERATED ALWAYS AS (a * 2), c int GENERATED ALWAYS AS (a * 3) STORED);
ALTER TABLE ty365 ALTER COLUMN a TYPE bigint;
CREATE TABLE ts365 (a int, c int GENERATED ALWAYS AS (a * 3) STORED);
ALTER TABLE ts365 ALTER COLUMN a TYPE numeric;
DROP TABLE t365, n365, ref365, l365, p365, p365b, ty365, ts365;
DROP FUNCTION f365(int), trg365();
DROP DOMAIN d365;
DROP TYPE mood365;
